// 寻找寻找相连的价值矿产
int bfs(vector<string>& ans, int i , int j, vector<vector<bool>>& visitd) {
    // 定义上下左右四个方向
    int direct[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    int res = 0;
    queue<pair<int, int>> pq;
    pq.push({i, j});

    while (!pq.empty()) {
        pair<int,int> p = pq.front();
        pq.pop();

        int x= p.first;
        int y = p.second;
        visitd[x][y] = 1;
        res += (ans[x][y] - '0');
        for (int i = 0; i < 4; i++) {
            int newX = x + direct[i][0];
            int newY = y + direct[i][1];
            if (newX < 0 || newY < 0 || newX >= ans.size() || newY >= ans[0].size()|| ans[newX][newY] == '0' || visitd[newX][newY]) {
                continue;
            }
            // 防止重复放入
            visitd[newX][newY] = 1;
            pq.push({newX, newY});
        }
    }
    return res;
}
