int main() {
    vector<string> ans;
    string s;
    while (cin >> s) {
        ans.push_back(s);
    }
    int n = ans.size();
    int m = ans[0].size();
    // 记录是否访问过
    vector<vector<bool>> visitd(n, vector<bool>(m, false));
    int res = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (ans[i][j] != '0' && !visitd[i][j]) {
                int tmp = bfs(ans, i, j, visitd);
                res = max(res, tmp);
            }
        }
    }
    cout << res;
    return 0;
}

