public class Main {
    // 寻找相连的价值矿产
    public static int bfs(List<String> ans, int i, int j, boolean[][] visited) {
        // 定义上下左右四个方向
        int[][] direct = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        int res = 0;
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{i, j});

        while (!queue.isEmpty()) {
            int[] p = queue.poll();
            int x = p[0], y = p[1];
            visited[x][y] = true;
            res += ans.get(x).charAt(y) - '0';

            for (int[] d : direct) {
                int newX = x + d[0];
                int newY = y + d[1];
                if (newX < 0 || newY < 0 || newX >= ans.size() || newY >= ans.get(0).length() || ans.get(newX).charAt(newY) == '0' || visited[newX][newY]) {
                    continue;
                }
                // 防止重复放入
                visited[newX][newY] = true;
                queue.offer(new int[]{newX, newY});
            }
        }
        return res;
    }
​
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        List<String> ans = new ArrayList<>();
        while (scanner.hasNext()) {
            ans.add(scanner.next());
        }
        scanner.close();

        int n = ans.size();
        int m = ans.get(0).length();
        boolean[][] visited = new boolean[n][m];
        int res = 0;

        // 遍历所有位置
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (ans.get(i).charAt(j) != '0' && !visited[i][j]) {
                    int tmp = bfs(ans, i, j, visited);
                    res = Math.max(res, tmp);
                }
            }
        }
        System.out.println(res);
    }
}
