package main
​
import (
    "bufio"
    "fmt"
    "os"
)
​
// BFS 寻找相连的价值矿产
func bfs(ans []string, i, j int, visited [][]bool) int {
    // 定义上下左右四个方向
    directions := [4][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}
    res := 0
    queue := [][2]int{{i, j}}
​
    for len(queue) > 0 {
        x, y := queue[0][0], queue[0][1]
        queue = queue[1:]
        visited[x][y] = true
        res += int(ans[x][y] - '0')
​
        for _, d := range directions {
            newX, newY := x+d[0], y+d[1]
            if newX >= 0 && newY >= 0 && newX < len(ans) && newY < len(ans[0]) && ans[newX][newY] != '0' && !visited[newX][newY] {
                visited[newX][newY] = true
                queue = append(queue, [2]int{newX, newY})
            }
        }
    }
    return res
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
    var ans []string
​
    // 读取输入
    for scanner.Scan() {
        ans = append(ans, scanner.Text())
    }
​
    n, m := len(ans), len(ans[0])
    visited := make([][]bool, n)
    for i := range visited {
        visited[i] = make([]bool, m)
    }
​
    res := 0
    // 遍历所有位置
    for i := 0; i < n; i++ {
        for j := 0; j < m; j++ {
            if ans[i][j] != '0' && !visited[i][j] {
                tmp := bfs(ans, i, j, visited)
                if tmp > res {
                    res = tmp
                }
            }
        }
    }
​
    // 输出结果
    fmt.Println(res)
}
